#include "database.h"
#include <cassert>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <string>

int main() {
    using namespace ml::sql;

    Field id;
    id.name = "id";
    id.type = FieldType::INT;
    id.is_id = true;
    id.auto_increment = true;
    assert(field_to_sql_definition(id, "mysql") == "id INT PRIMARY KEY AUTO_INCREMENT");
    assert(field_to_sql_definition(id, "postgresql") ==
           "id INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY");

    Model model;
    model.name = "Account";
    model.table_name = "accounts";
    model.fields.push_back(id);
    Field email;
    email.name = "email";
    email.type = FieldType::STRING;
    email.is_unique = true;
    model.fields.push_back(email);

    CRUDGenerator mysql_generator(model, "mysql");
    CRUDGenerator postgres_generator(model, "postgresql");
    assert(mysql_generator.generate_create_table().find("AUTO_INCREMENT") != std::string::npos);
    assert(postgres_generator.generate_create_table().find("GENERATED BY DEFAULT AS IDENTITY") !=
           std::string::npos);
    assert(mysql_generator.generate_find_by_id() == "SELECT * FROM accounts WHERE id = ?");
    assert(postgres_generator.generate_find_by_id() == "SELECT * FROM accounts WHERE id = ?");

    auto database = Database::create("sqlite");
    assert(database->get_provider() == "sqlite");
    assert(database->connect(":memory:"));
    const auto unique = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path() /
        ("coolbox_sql_migration_test_" + std::to_string(unique));
    std::filesystem::create_directories(directory);
    {
        std::ofstream up(directory / "0001_create_users.up.sql");
        up << "CREATE TABLE users (id INTEGER PRIMARY KEY);";
        std::ofstream down(directory / "0001_create_users.down.sql");
        down << "DROP TABLE users;";
    }
    {
        std::ofstream up(directory / "0002_create_posts.up.sql");
        up << "CREATE TABLE posts (id INTEGER PRIMARY KEY);";
        std::ofstream down(directory / "0002_create_posts.down.sql");
        down << "DROP TABLE posts;";
    }
    MigrationRunner runner(*database, directory.string());
    runner.migrate_up();
    assert(runner.current_version() == "0002");
    runner.migrate_down();
    assert(runner.current_version() == "0001");
    std::filesystem::remove_all(directory);
}
